@page "/settings"
@rendermode InteractiveServer
@using sv_9f99ee7accfe4323820e90a171159607.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">×</button>
            </div>
        }

        @if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (profile is not null)
                {
                    <div class="avatar-area">
                        <img src="@editProfile.AvatarUrl" alt="Avatar" class="avatar-preview" />
                        <span class="avatar-url">@editProfile.AvatarUrl</span>
                    </div>
                    <div class="form-group">
                        <label for="displayName">Display Name</label>
                        <input id="displayName" type="text" @bind="editProfile.DisplayName" />
                    </div>
                    <div class="form-group">
                        <label for="email">Email</label>
                        <input id="email" type="email" @bind="editProfile.Email" />
                    </div>
                    <div class="form-group">
                        <label for="bio">Bio</label>
                        <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                        <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (notificationPrefs is not null)
                {
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                            <span class="toggle-switch"></span>
                            Email Notifications
                        </label>
                    </div>
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <input type="checkbox" @bind="editNotifications.PushNotifications" />
                            <span class="toggle-switch"></span>
                            Push Notifications
                        </label>
                    </div>
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                            <span class="toggle-switch"></span>
                            Weekly Digest
                        </label>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in allChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@editNotifications.MutedChannels.Contains(channel)"
                                       @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                @channel
                            </label>
                        }
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (security is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                        </button>
                        @if (showPasswordPanel)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label for="currentPassword">Current Password</label>
                                    <input id="currentPassword" type="password" @bind="currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="newPassword">New Password</label>
                                    <input id="newPassword" type="password" @bind="newPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="confirmPassword">Confirm Password</label>
                                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                </div>
                                <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="toggle-group security-toggle">
                        <label class="toggle-label">
                            <input type="checkbox" @bind="twoFactorEnabled" />
                            <span class="toggle-switch"></span>
                            Two-Factor Authentication
                        </label>
                        <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                            @(twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>

                    @if (security.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != currentSessionId)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>

                    @if (showRevokeConfirmation)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Confirm Session Revocation</h3>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (appearance is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Light" checked="@(editAppearance.Theme == "Light")" @onchange='() => editAppearance.Theme = "Light"' />
                                Light
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Dark" checked="@(editAppearance.Theme == "Dark")" @onchange='() => editAppearance.Theme = "Dark"' />
                                Dark
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="System" checked="@(editAppearance.Theme == "System")" @onchange='() => editAppearance.Theme = "System"' />
                                System
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Small" checked="@(editAppearance.FontSize == "Small")" @onchange='() => editAppearance.FontSize = "Small"' />
                                Small
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Medium" checked="@(editAppearance.FontSize == "Medium")" @onchange='() => editAppearance.FontSize = "Medium"' />
                                Medium
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Large" checked="@(editAppearance.FontSize == "Large")" @onchange='() => editAppearance.FontSize = "Large"' />
                                Large
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="language">Language</label>
                        <select id="language" @bind="editAppearance.Language">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>

                    <div class="toggle-group">
                        <label class="toggle-label">
                            <input type="checkbox" @bind="editAppearance.CompactMode" />
                            <span class="toggle-switch"></span>
                            Compact Mode
                        </label>
                    </div>

                    <h3>Live Preview</h3>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">Preview Header</div>
                        <div class="preview-body">
                            <p>This is how your content will look with the selected settings.</p>
                            <p>Theme: @editAppearance.Theme | Font: @editAppearance.FontSize | Lang: @editAppearance.Language</p>
                            @if (editAppearance.CompactMode)
                            {
                                <p><em>Compact mode is enabled — reduced spacing.</em></p>
                            }
                        </div>
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
            </section>
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    // Toast
    private string? toastMessage;
    private string toastType = "success";

    // Profile
    private UserProfile? profile;
    private ProfileEdit editProfile = new();

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private NotificationEdit editNotifications = new();
    private readonly List<string> allChannels = ["announcements", "marketing", "social", "engineering", "general"];

    // Security
    private SecuritySettings? security;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool twoFactorEnabled;
    private string currentSessionId = "sess-1";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? appearance;
    private AppearanceEdit editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section)
    {
        activeSection = section;
        DismissToast();
    }

    // --- Profile ---
    private async Task LoadProfile()
    {
        profile = await SettingsService.GetProfileAsync();
        editProfile = new ProfileEdit
        {
            DisplayName = profile.DisplayName,
            Email = profile.Email,
            AvatarUrl = profile.AvatarUrl,
            Bio = profile.Bio
        };
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editProfile.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (profile is not null)
        {
            editProfile = new ProfileEdit
            {
                DisplayName = profile.DisplayName,
                Email = profile.Email,
                AvatarUrl = profile.AvatarUrl,
                Bio = profile.Bio
            };
        }
    }

    // --- Notifications ---
    private async Task LoadNotifications()
    {
        notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        editNotifications = new NotificationEdit
        {
            EmailNotifications = notificationPrefs.EmailNotifications,
            PushNotifications = notificationPrefs.PushNotifications,
            WeeklyDigest = notificationPrefs.WeeklyDigest,
            MutedChannels = new List<string>(notificationPrefs.MutedChannels)
        };
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !editNotifications.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(
            editNotifications.EmailNotifications,
            editNotifications.PushNotifications,
            editNotifications.WeeklyDigest,
            new List<string>(editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // --- Security ---
    private async Task LoadSecurity()
    {
        security = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = security.TwoFactorEnabled;
    }

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword) || newPassword != confirmPassword)
        {
            ShowToast("Passwords do not match or are empty.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            await LoadSecurity();
            ShowToast($"Session on {sessionToRevoke.Device} has been revoked.", "success");
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // --- Appearance ---
    private async Task LoadAppearance()
    {
        appearance = await SettingsService.GetAppearanceAsync();
        editAppearance = new AppearanceEdit
        {
            Theme = appearance.Theme,
            FontSize = appearance.FontSize,
            Language = appearance.Language,
            CompactMode = appearance.CompactMode
        };
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editAppearance.Theme.ToLowerInvariant()} preview-font-{editAppearance.FontSize.ToLowerInvariant()}";
        if (editAppearance.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(editAppearance.Theme, editAppearance.FontSize, editAppearance.Language, editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        appearance = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    // --- Toast ---
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
    }

    private void DismissToast() => toastMessage = null;

    // --- Helpers ---
    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} minutes ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // --- Edit Models ---
    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = [];
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
    background: #f8f9fa;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 2px 12px rgba(0,0,0,0.08);
    margin: 1rem;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #1e293b;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.85rem 1.5rem;
    cursor: pointer;
    color: #94a3b8;
    font-weight: 500;
    transition: all 0.2s;
    border-left: 3px solid transparent;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.settings-sidebar li:hover {
    background: #334155;
    color: #e2e8f0;
}

.settings-sidebar li.active {
    background: #334155;
    color: #ffffff;
    border-left-color: #3b82f6;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1e293b;
    font-size: 1.5rem;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    color: #334155;
}

/* Toast */
.toast {
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    animation: slideDown 0.3s ease;
}

.toast.success {
    background: #dcfce7;
    color: #166534;
    border: 1px solid #86efac;
}

.toast.error {
    background: #fef2f2;
    color: #991b1b;
    border: 1px solid #fca5a5;
}

.toast-close {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: inherit;
    padding: 0 0.25rem;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #374151;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

/* Avatar */
.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e5e7eb;
}

.avatar-url {
    font-size: 0.85rem;
    color: #6b7280;
    word-break: break-all;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: #3b82f6;
    color: white;
}

.btn-primary:hover {
    background: #2563eb;
}

.btn-secondary {
    background: #e5e7eb;
    color: #374151;
}

.btn-secondary:hover {
    background: #d1d5db;
}

.btn-danger {
    background: #ef4444;
    color: white;
}

.btn-danger:hover {
    background: #dc2626;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-weight: 500;
    color: #374151;
}

.toggle-label input[type="checkbox"] {
    width: 40px;
    height: 22px;
    appearance: none;
    background: #d1d5db;
    border-radius: 11px;
    position: relative;
    cursor: pointer;
    transition: background 0.2s;
    flex-shrink: 0;
}

.toggle-label input[type="checkbox"]::after {
    content: '';
    position: absolute;
    top: 2px;
    left: 2px;
    width: 18px;
    height: 18px;
    background: white;
    border-radius: 50%;
    transition: transform 0.2s;
}

.toggle-label input[type="checkbox"]:checked {
    background: #3b82f6;
}

.toggle-label input[type="checkbox"]:checked::after {
    transform: translateX(18px);
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    cursor: pointer;
}

.channel-item input[type="checkbox"] {
    width: 16px;
    height: 16px;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    padding: 1rem 1.25rem;
    background: white;
    border: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #374151;
}

.panel-header:hover {
    background: #f9fafb;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e5e7eb;
    background: #f9fafb;
}

/* Security toggle */
.security-toggle {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-weight: 600;
}

.status-indicator.enabled {
    background: #dcfce7;
    color: #166534;
}

.status-indicator.disabled {
    background: #fef2f2;
    color: #991b1b;
}

.info-text {
    color: #6b7280;
    font-size: 0.85rem;
    margin: 0.5rem 0;
}

.current-badge {
    font-size: 0.8rem;
    background: #dbeafe;
    color: #1e40af;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-weight: 500;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    background: white;
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #e5e7eb;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid #e5e7eb;
}

.sessions-table th {
    background: #f8fafc;
    font-weight: 600;
    color: #374151;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.025em;
}

.sessions-table tr:last-child td {
    border-bottom: none;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal {
    background: white;
    padding: 2rem;
    border-radius: 12px;
    max-width: 440px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0,0,0,0.2);
}

.modal h3 {
    margin-top: 0;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Live preview */
.live-preview {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 1rem;
    transition: all 0.3s;
}

.preview-header {
    padding: 0.75rem 1rem;
    font-weight: 600;
    border-bottom: 1px solid #e5e7eb;
}

.preview-body {
    padding: 1rem;
}

.preview-body p {
    margin: 0.4rem 0;
}

/* Preview theme variations */
.preview-theme-light {
    background: #ffffff;
    color: #1e293b;
}

.preview-theme-light .preview-header {
    background: #f8fafc;
}

.preview-theme-dark {
    background: #1e293b;
    color: #e2e8f0;
    border-color: #475569;
}

.preview-theme-dark .preview-header {
    background: #0f172a;
    border-color: #475569;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e293b 50%);
    color: #374151;
}

.preview-theme-system .preview-header {
    background: #f0f9ff;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact */
.preview-compact .preview-header {
    padding: 0.4rem 0.75rem;
}

.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.preview-compact .preview-body p {
    margin: 0.15rem 0;
}

